insert into reviewer_private.curated_skills(id,kit)
select item->>'id', item from jsonb_array_elements($kits$[{"id":"verbal-main-idea","title":"Finding the main idea","lesson":"Name the shared subject, then ask what the passage says about it as a whole. A detail supports the main idea without covering everything.","example":"“Mia checks her bike tires and tests its brakes before every trip.” Both actions support one idea: Mia prepares her bike for a safe ride.","rows":[["Rosa labels her folders, sorts them by topic, and keeps an index. What is the main idea?","Rosa writes labels.","Rosa organizes her records systematically.",1,"The labels, sorting and index all help organize records. Labels alone cover only one action."],["A school planted trees, added shade screens, and moved assemblies indoors on hotter days. What connects the actions?","The school stopped holding assemblies.","The school reduced heat exposure.",1,"Every action protects people from heat. The passage only says some assemblies moved indoors."],["Which summary fits a paragraph about low-cost repairs that extended the life of three devices?","New devices always cost too much.","Small repairs helped devices last longer.",1,"The repairs and their benefit appear in each example. The paragraph need not claim anything about all new devices."],["Two neighbors disagreed on paint color but both repaired broken steps before repainting. What is the main shared idea?","They chose the same colors.","They addressed safety before appearance.",1,"Both repaired the steps first. Their colors differed, so color agreement cannot be the main shared idea."],["Shop A wastes less food by ordering smaller batches. Shop B offers discounts before items expire. Which title covers both?","Why All Shops Need Smaller Orders","Two Ways Shops Reduce Food Waste",1,"The goal is shared but the methods differ. A smaller-order title would exclude Shop B."],["A bus route added an early trip for workers and a late trip for students. What is the best summary?","The schedule was expanded for different riders.","The route now carries only students.",0,"One extra trip serves workers and the other serves students. Both changes belong in the summary."]]},{"id":"verbal-pronouns","title":"Clear pronoun reference","lesson":"A pronoun stands in for another word. The reader should be able to identify its antecedent, the person or thing it names, without guessing.","example":"“Lena lent Maya a ruler because she forgot one.” Repeating “Maya” instead of “she” makes clear who forgot the ruler.","rows":[["In “The lamp is old, but it still works,” what does “it” refer to?","The age","The lamp",1,"The thing that works is the lamp. “Old” describes the lamp but does not name a thing."],["Which version clearly says Nia needs the schedule?","Nia told Bea that she needed the schedule.","Nia said to Bea, “I need the schedule.”",1,"The quoted speaker is Nia, so “I” identifies her. In the first version “she” could name either person."],["Which revision says the notebook fell?","When the bag opened, it fell.","The notebook fell out of the bag.",1,"Naming the notebook makes the subject explicit. In the second version “it” could be the bag."],["“The clerk sent the forms to the managers. They signed them.” What does “them” mean?","The forms","The managers",0,"The managers sign the forms. “Them” is the object of the signing action."],["Rewrite so Kai was late: “Kai called Drew because they were late.”","Because they were late, Kai called Drew.","Kai called Drew because Kai was late.",1,"Moving the ambiguous pronoun does not resolve its reference. Naming Kai does."],["“The coach showed the captain a photo before she left.” Can we tell who left?","No, either person might have left.","Yes, the captain necessarily left.",0,"Both people could fit the pronoun. A closer noun does not guarantee that it is the intended reference."]]},{"id":"filipino-synonyms","title":"Kasingkahulugan","lesson":"Magkasingkahulugan ang mga salitang malapit ang ibig sabihin. Suriin din kung ang ipapalit ay akma sa pangungusap.","example":"Sa “masaya ang bata,” maaaring ipalit ang “maligaya” dahil kapwa naglalarawan ng saya.","rows":[["Alin ang kasingkahulugan ng “masaya”?","Malungkot","Maligaya",1,"Ang maligaya ay may saya. Ang malungkot ay kabaligtaran."],["“Munti ang silid.” Ano ang kasingkahulugan ng munti?","Malawak","Maliit",1,"Inilalarawan ng munti ang maliit na sukat. Ang malawak ay tumutukoy sa malaking espasyo."],["“Tahimik ang silid.” Alin ang pinakamalapit ang kahulugan?","Walang ingay ang silid.","Maliwanag ang silid.",0,"Ang tahimik ay tungkol sa tunog. Ang maliwanag ay tungkol sa liwanag."],["“Agad tumugon ang guro.” Alin ang maaaring ipalit sa “agad”?","Kaagad","Minsan",0,"Ang agad at kaagad ay tumutukoy sa pagkilos nang walang paghihintay. Ang minsan ay tumutukoy sa dalas."],["“Matiyaga siyang nag-ensayo.” Alin ang pinakamalapit dito?","Huminto siya nang mahirapan.","Nagpatuloy siya kahit mahirap.",1,"Ang pagtitiyaga ay pagpapatuloy sa kabila ng hirap. Ang paghinto ay salungat dito."],["“Salat sa tubig ang lugar.” Alin ang kapareho ng diwa?","Kulang sa tubig ang lugar.","Sagana sa tubig ang lugar.",0,"Ang salat ay kulang. Ang sagana ay marami o sapat nang higit sa kailangan."]]},{"id":"filipino-antonyms","title":"Kasalungat","lesson":"Hanapin ang salitang kabaligtaran sa parehong katangian. Tukuyin muna kung ang pangungusap ay tungkol sa sukat, dami, damdamin o ibang katangian.","example":"Magkasalungat ang mahaba at maikli kapag haba ang pinag-uusapan.","rows":[["Alin ang kasalungat ng “malayo”?","Mataas","Malapit",1,"Ang malapit at malayo ay magkasalungat na distansiya. Ang mataas ay tungkol sa taas."],["Alin ang kasalungat ng tahimik?","Maingay","Mabagal",0,"Tunog ang sinusukat: kaunti ang tunog kung tahimik, marami kung maingay."],["“Lantad ang pagkakamali.” Ano ang kasalungat ng lantad?","Nakasulat","Nakatago",1,"Ang lantad ay nakikita o hayag. Ang nakatago ang kabaligtaran."],["“Malabo ang larawan.” Alin ang kabaligtaran?","Malinaw ang larawan.","Makapal ang larawan.",0,"Ang malabo at malinaw ay tungkol sa linaw ng larawan. Ang kapal ay ibang katangian."],["“Magaan ang kahon.” Ano ang pinakamalinaw na kasalungat sa kontekstong ito?","Mabigat","Mahirap",0,"Timbang ng kahon ang tinutukoy. Ang mahirap ay angkop sa antas ng isang gawain."],["“Palagi siyang dumarating nang maaga.” Alin ang kumokontra sa oras ng pagdating, habang pareho ang dalas?","Palagi siyang dumarating nang huli.","Minsan siyang dumarating nang maaga.",0,"Nananatili ang palagi. Nagbago ang oras mula maaga tungo sa huli."]]},{"id":"analytical-assumptions","title":"Finding necessary assumptions","lesson":"An assumption is an unstated idea that an argument depends on. Negate a proposed assumption and ask whether the argument still works.","example":"“The key opens the cabinet because it came with the cabinet.” That argument assumes the cabinet still uses the same lock.","rows":[["“The battery will power the radio because it is fully charged.” Which assumption is required?","The radio is blue.","The battery is compatible with the radio.",1,"Without compatibility the charge is insufficient. The radio color changes nothing."],["“Moving the meeting online will let Jo attend from home.” Which unstated condition matters?","Jo has a way to join the online meeting.","Jo owns a large monitor.",0,"Without access Jo still cannot attend. A large monitor is unnecessary."],["“Everyone in the room signed the sheet, so Bea signed it.” Which fact is assumed?","Bea was in the room.","Bea wrote her name neatly.",0,"The conclusion applies the room-wide rule to Bea. Her handwriting quality is irrelevant."],["“The trip will take one hour because it is 60 km at 60 km/h.” What assumption supports the prediction?","Fuel costs are unchanged.","The average speed over the full route is 60 km/h.",1,"Distance divided by average speed gives travel time. Fuel cost does not enter the calculation."],["“We can fit both purchases within the budget because together they cost ₱600 and the budget is ₱650.” Which assumption is needed?","No required fees push the total above ₱650.","Both purchases are from the same seller.",0,"Extra unavoidable fees could break the conclusion. Seller identity does not affect the inequality by itself."],["“This sample result describes all employees because 90% of the respondents agreed.” Which assumption deserves scrutiny?","The respondents represent the wider employee group.","The survey was printed in color.",0,"A response percentage describes respondents. Applying it to all employees depends on representative coverage."]]},{"id":"clerical-numeric","title":"Numeric filing keys","lesson":"Read a numeric filing key as a number when the rule calls for numeric order. Apply a later key only if the earlier key ties.","example":"In ascending numeric order, 9 comes before 12. Comparing the first digit as text would wrongly place 12 first.","rows":[["In ascending numeric order, which file goes first?","7","11",0,"7 is a smaller number than 11. Comparing the first printed digit would give the wrong order."],["In descending numeric order, which file goes first?","19","23",1,"Descending means greatest first. 23 is greater than 19."],["Leading zeros do not change the numeric key. Which pair ties?","040 and 4","004 and 4",1,"004 has numeric value 4. The 4 in 040 is in the tens place and means 40."],["File by ascending number, then surname. Which goes first?","9 — Cruz","12 — Abad",0,"Compare the number before the surname. 9 comes first even though Cruz comes after Abad alphabetically."],["File by ascending number, then surname. Which goes first?","12 — Cruz","12 — Abad",1,"The number ties, so compare Abad and Cruz. A precedes C."],["File in ascending numeric order. Where does 102 go among 19, 26 and 110?","Before 19","Between 26 and 110",1,"102 is greater than 26 and smaller than 110. Its first digit does not decide the order."]]},{"id":"clerical-transcription","title":"Accurate transcription","lesson":"Compare a copy against the original in small groups. In exact transcription, case, punctuation and digit order matter unless the rule allows a change.","example":"Copying “RM-401” as “RM-410” swaps the last two digits. Compare “RM”, the hyphen and then each digit to locate the error.","rows":[["Copy “AB-19” exactly. Which copy is correct?","AB-91","AB-19",1,"The original ends in 19. In AB-91 the two digits have changed order."],["Copy “Blk. 7” exactly. Which copy is correct?","Blk. 7","Blk 7",0,"The period after Blk is present in the original. The other copy omits it."],["Original “ID-0052”, copy “ID-052”. What changed?","A zero was omitted.","The final digits were swapped.",0,"The original has two zeros before 52. The copy has one, and 52 has kept its order."],["Which exact copy preserves the case in “De la Cruz”?","De la Cruz","De La Cruz",0,"The original has a lowercase l in la. Exact copying preserves it."],["Original “M-18 / R-42”, copy “M-18 / R-24”. Where is the error?","Both codes","Second code only",1,"M-18 matches exactly. The second code reverses the 4 and 2."],["Match “ZX-061, 09:15” exactly. Which entry matches?","ZX-061, 09:15","ZX-061, 9:15",0,"The leading zero in 09 is part of the original text. Equivalent time values are insufficient in exact transcription."]]},{"id":"government-branches","title":"Branches of Philippine government","lesson":"Distinguish the powers of Congress, the President and the courts. The 1987 Constitution sets out these branches in Articles VI, VII and VIII.","example":"Congress considers changes to a law. The executive carries out the law. A court may interpret and apply it when deciding a case.","rows":[["Under Article VI, which institution generally exercises legislative power?","The Supreme Court","Congress",1,"Article VI, Section 1 assigns legislative power to Congress, subject to the constitutional provision for initiative and referendum."],["Which two chambers form Congress?","The Senate and House of Representatives","The Cabinet and Senate",0,"Article VI, Section 1 names these chambers. The Cabinet belongs to the executive branch."],["Which branch is headed by the President under Article VII?","Executive","Judicial",0,"Article VII, Section 1 vests executive power in the President. Article VIII establishes the judicial branch."],["A court decides a concrete dispute over an enforceable right. Which power is it exercising?","Legislative power","Judicial power",1,"Article VIII, Section 1 includes deciding actual controversies involving enforceable rights. The court is resolving a case."],["A department implements an enacted law while lawmakers debate an amendment. Which action belongs to the executive branch?","Implementing the enacted law","Debating the amendment in Congress",0,"Article VII, Section 17 addresses faithful execution of laws. Debating an amendment in Congress is part of the legislative process."],["Which claim correctly describes the constitutional structure?","The Supreme Court is the only possible court.","Judicial power includes the Supreme Court and lower courts established by law.",1,"Article VIII, Section 1 expressly provides for lower courts established by law alongside the Supreme Court."]]}]$kits$::jsonb) item
on conflict (id) do nothing;
